import * as THREE from 'three/webgpu';
import { texture as tslTexture } from 'three/tsl';

export default function createNode(config, ctx) {
  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load the brushed metal texture
  const textureAsset = ctx.textureLoader.load(config.assets.imageUrl);
  textureAsset.colorSpace = THREE.SRGBColorSpace;

  // Create material using TSL nodes for color
  const colorNode = tslTexture(textureAsset);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: colorNode,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement from config
  const scenePos = config.scenePosition;
  if (scenePos) {
    mesh.position.set(scenePos.x, scenePos.y, scenePos.z);
  }

  const sceneRot = config.sceneRotation;
  if (sceneRot) {
    mesh.rotation.set(sceneRot.x, sceneRot.y, sceneRot.z);
  }

  const sceneScale = config.sceneScale;
  if (sceneScale) {
    mesh.scale.set(sceneScale.x, sceneScale.y, sceneScale.z);
  }

  // Initialize userData
  mesh.userData.handlers = {};

  // Cleanup function
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureAsset.dispose();
  };

  return mesh;
}
